const ArgumentType = require("../../extension-support/argument-type");
const BlockType = require("../../extension-support/block-type");
const msg = require("./translation");
const formatMessage = require("format-message");

const menuIconURI =
    " data:image/png;base64,";
const blockIconURI =
    "data:image/png;base64,";

//const defaultId = "default";

let theLocale = null;

var speechText = "";
var recognizing = false; // 是否辨識中
var recognition = new webkitSpeechRecognition();

recognition.continuous = true;
recognition.interimResults = true;
var u_set_lang="cmn-Hant-TW";
const lang_ary=['cmn-Hant-TW','en-US','ja-JP','ko-KR','cmn-Hans-CN','yue-Hant-HK'];
recognition.lang = u_set_lang;
//cmn-en-US
recognition.onresult = function (event) {
    var resultIndex = event.resultIndex;
    var length = event.results[resultIndex].length - 1;
    var isFinal = event.results[resultIndex].isFinal;

    if (isFinal) speechText = event.results[resultIndex][length].transcript;
};

addEventListener;

class voicetoTEXT {
    constructor(runtime) {
        theLocale = this._setLocale();
        this.runtime = runtime;
        // communication related
        this.comm = runtime.ioDevices.comm;
        this.session = null;
        this.runtime.registerPeripheralExtension("voicetoTEXT", this);
        // session callbacks
        this.reporter = null;
        this.onmessage = this.onmessage.bind(this);
        this.onclose = this.onclose.bind(this);
        this.write = this.write.bind(this);
        // string op
        this.decoder = new TextDecoder();
        this.lineBuffer = "";

    }

    onclose() {
        this.session = null;
    }

    write(data, parser = null) {
        if (this.session) {
            return new Promise((resolve) => {
                if (parser) {
                    this.reporter = {
                        parser,
                        resolve,
                    };
                }
                this.session.write(data);
            });
        }
    }

    onmessage(data) {
        const dataStr = this.decoder.decode(data);
        this.lineBuffer += dataStr;
        if (this.lineBuffer.indexOf("\n") !== -1) {
            const lines = this.lineBuffer.split("\n");
            this.lineBuffer = lines.pop();
            for (const l of lines) {
                if (this.reporter) {
                    const { parser, resolve } = this.reporter;
                    resolve(parser(l));
                }
            }
        }
    }

    scan() {
        this.comm.getDeviceList().then((result) => {
            this.runtime.emit(
                this.runtime.constructor.PERIPHERAL_LIST_UPDATE,
                result
            );
        });
    }

    _setLocale() {
        let nowLocale = "";
        switch (formatMessage.setup().locale) {
            case "zh-tw":
                nowLocale = "zh-tw";
                break;
            default:
                nowLocale = "en";
                break;
        }
        return nowLocale;
    }

    getInfo() {
        theLocale = this._setLocale();

        return {
            id: "voicetoTEXT",
            name: msg.name[theLocale],
            color1: "#595a5c",
            color2: "#595a5c",
            menuIconURI: menuIconURI,
            blockIconURI: blockIconURI,
            blocks: [
                {
                    opcode: "setLang",
                    blockType: BlockType.COMMAND,
                    text: msg.setLang[theLocale],
                    arguments: {
                        LANG:{
                            type: ArgumentType.STRING,
                            defaultValue: msg.lang_List[theLocale][0],
                            menu:'lang'
                        }
                    }
                },
                {
                    opcode: "beginVoice",
                    blockType: BlockType.COMMAND,
                    text: msg.beginVoice[theLocale],
                    
                },
                {
                    opcode: "pauseVoice",
                    blockType: BlockType.COMMAND,
                    text: msg.pauseVoice[theLocale],
                },
                {
                    opcode: "nullTEXT",
                    blockType: BlockType.COMMAND,
                    text: msg.nullTEXT[theLocale],
                },
                {
                    opcode: "voicetoTEXT",
                    blockType: BlockType.REPORTER,
                    arguments: {
                        id: {
                            type: ArgumentType.STRING,
                            defaultValue: "id",
                        },
                    },
                    text: msg.voicetoTEXT[theLocale],
                },
            ],
            menus: {
                lang: {
                    acceptReporters: true,
                    items: msg.lang_List[theLocale],
                },
            }
        };
    }

    setLang(args){
        let s_lang=args.LANG;
        console.log('lang=',s_lang);
        console.log('lang_set=',lang_ary[msg.lang_List[theLocale].indexOf(s_lang)]);
        u_set_lang =lang_ary[msg.lang_List[theLocale].indexOf(s_lang)];
    }

    beginVoice() {
        speechText = "";
        console.log('u_set_lang=',u_set_lang);
        recognition.abort();
        recognition.lang = u_set_lang;
        recognition.start()        
    }

    pauseVoice() {
        recognition.abort();
    }

    nullTEXT() {
        return (speechText = "");
    }

    voicetoTEXT() {
        return speechText;
    }
}

module.exports = voicetoTEXT;
