const ArgumentType = require('../../extension-support/argument-type');
const BlockType = require('../../extension-support/block-type');
const msg = require('./translation');
const formatMessage = require('format-message');
const fetchWithTimeout = require('../../util/fetch-with-timeout');

const ml5 = require('ml5');

const menuIconURI = `data:image/png;base64,`;
const blockIconURI = menuIconURI;

const defaultId = 'default';
let theLocale = null;

class textSentiment {
    constructor(runtime) {
        theLocale = this._setLocale();
        this.runtime = runtime;
        // communication related
        this.comm = runtime.ioDevices.comm;
        this.session = null;
        this.runtime.registerPeripheralExtension('facePerception', this);
        // session callbacks
        this.reporter = null;
        this.onmessage = this.onmessage.bind(this);
        this.onclose = this.onclose.bind(this);
        this.write = this.write.bind(this);

        // 設定文字情緒的置信度
        this.confidence = 0;
        this.text='hello';
        // 載入 ML5 Sentiment Model 
        this.sentiment = ml5.sentiment('MovieReviews');
    }

    onclose() {
        this.session = null;
    }

    write(data, parser = null) {
        if (this.session) {
            return new Promise(resolve => {
                if (parser) {
                    this.reporter = {
                        parser,
                        resolve
                    };
                }
                this.session.write(data);
            });
        }
    }

    onmessage(data) {
        const dataStr = this.decoder.decode(data);
        this.lineBuffer += dataStr;
        if (this.lineBuffer.indexOf('\n') !== -1) {
            const lines = this.lineBuffer.split('\n');
            this.lineBuffer = lines.pop();
            for (const l of lines) {
                if (this.reporter) {
                    const { parser, resolve } = this.reporter;
                    resolve(parser(l));
                }
            }
        }
    }

    scan() {
        this.comm.getDeviceList().then(result => {
            this.runtime.emit(this.runtime.constructor.PERIPHERAL_LIST_UPDATE, result);
        });
    }

    _setLocale() {
        let nowLocale = '';
        switch (formatMessage.setup().locale) {
            case 'zh-tw':
                nowLocale = 'zh-tw';
                break;
            default:
                nowLocale = 'en';
                break;
        }
        return nowLocale;
    }

    getInfo() {
        theLocale = this._setLocale();

        return {
            id: 'textSentiment',
            name: msg.title[theLocale],
            color1: '#3AACFD',
            color2: '#3AACFD',
            menuIconURI: menuIconURI,
            blockIconURI: blockIconURI,
            blocks: [
                {
                    opcode: 'inputText',
                    blockType: BlockType.COMMAND,
                    arguments: {
                        defaultText: {
                            type: ArgumentType.STRING,
                            defaultValue: msg.defaultText[theLocale]
                        },
                    },
                    text: msg.inputText[theLocale]
                },
                {
                    opcode: 'startTextSentiment',
                    blockType: BlockType.COMMAND,
                    text: msg.startTextSentiment[theLocale]
                },
                {
                    opcode: 'getConfidence',
                    blockType: BlockType.REPORTER,
                    text: msg.confidence[theLocale]
                },
            ],
        };
    }

    inputText(args) {
        var words = args.defaultText;

        this.translateToEnglish(words);
    }

    async translateToEnglish(words) {
        //提出數字陣列
        let aa = words.match(/\d+(\.\d+)?/g);
        //console.log('aa=',aa);
        let endtext=words;
        if(aa!=null){
            if(aa.length>0){
                for (let step = 0; step < aa.length; step++) {
                    // Runs 5 times, with values of step 0 through 4.
                    endtext = words.replace(aa[step],' '+aa[step]);
                }
                
            }
        }        
        console.log('endtext=',endtext);

        //let urlBase = `https://translate-service.scratch.mit.edu/translate?language=en&text=` + encodeURIComponent(words);
        const cors_url=`https://script.google.com/macros/s/AKfycbw1NlgIow437hbalepBnPBIOWiLdEU8ZqhS-CVI2nBD1V1nY2Y-mMFSzSK9YUbE7waH/exec`;
            const translatePromise = await fetchWithTimeout(cors_url+'?lang=en&t='+encodeURIComponent(endtext), {}, 10000)
            .then(response => response.text())
            .then(responseText => {
                //const translated = JSON.parse(responseText).result;
                this.text = JSON.parse(responseText).result; //translated;   
                console.log('text=',this.text);             
            });
            
    }

    async startTextSentiment() {       
        this.confidence = await this.sentiment.predict(this.text)["score"];
    }

    /*sleep(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }*/

    getConfidence() {
        return this.confidence.toFixed(2);
    }
}

module.exports = textSentiment;
